const panel=document.createElement('section');panel.id='backupRestorePanel';panel.className='backup-restore-panel';panel.innerHTML=`<div><span class="backup-kicker">DATA SAFETY</span><h2>Backup & Restore</h2><p>Download a JSON backup of bookings, tour edits, category images and business settings.</p><div class="backup-meta"><span id="backupBookingsCount">0 bookings</span><span id="backupToursCount">0 tours</span><span id="backupLastTime">No backup created yet</span></div></div><div class="backup-actions"><button class="primary" id="createBackupBtn">↓ Create Backup</button><button class="restore-btn" id="restoreBackupBtn">↥ Restore Backup</button><input id="restoreBackupFile" type="file" accept="application/json,.json" hidden></div><div id="backupStatus" class="backup-status"></div>`;const dg=overview.querySelector('.dashboard-grid');if(dg)dg.before(panel);else overview.appendChild(panel);const $id=id=>document.getElementById(id);function readArray(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch{return[]}}function updateMeta(){const b=readArray('phoenixBookings'),t=readArray('phoenixAdminTours'),last=localStorage.getItem('phoenixLastBackup');$id('backupBookingsCount').textContent=`${b.length} booking${b.length===1?'':'s'}`;$id('backupToursCount').textContent=`${t.length} tour${t.length===1?'':'s'}`;$id('backupLastTime').textContent=last?`Last backup: ${new Date(last).toLocaleString()}`:'No backup created yet'}function status(m,type='ok'){const el=$id('backupStatus');el.textContent=m;el.className=`backup-status show ${type}`;setTimeout(()=>el.className='backup-status',5000)}function createBackup(){try{const now=new Date().toISOString();localStorage.setItem('phoenixLastBackup',now);const storage={};STORAGE_KEYS.forEach(k=>{const v=localStorage.getItem(k);if(v!==null)storage[k]=v});const blob=new Blob([JSON.stringify({format:'phoenix-tours-backup',version:2,createdAt:now,app:'Phoenix Tours Admin',storage},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`phoenix-tours-backup-${now.slice(0,10)}.json`;a.click();URL.revokeObjectURL(u);updateMeta();status('Backup created successfully.')}catch{status('Could not create backup.','err')}}async function restoreFile(file){try{const backup=JSON.parse(await file.text());if(backup?.format!=='phoenix-tours-backup'||!backup.storage)throw 0;if(!confirm('Restore this Phoenix Tours backup? Current browser data will be replaced.'))return;STORAGE_KEYS.forEach(k=>{if(typeof backup.storage[k]==='string'){JSON.parse(backup.storage[k]);localStorage.setItem(k,backup.storage[k])}});status('Backup restored. Reloading…');setTimeout(()=>location.reload(),600)}catch{status('Invalid Phoenix Tours backup file.','err')}}$id('createBackupBtn').onclick=createBackup;$id('restoreBackupBtn').onclick=()=>$id('restoreBackupFile').click();$id('restoreBackupFile').onchange=e=>{const f=e.target.files?.[0];if(f)restoreFile(f)};updateMeta();
